def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # A diagonal pair continues outward from both ends until it meets
    # another colored cell or reaches the edge.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                nr, nc = r + dr, c + dc
                if not (0 <= nr < h and 0 <= nc < w):
                    continue
                if grid[nr][nc] != color:
                    continue

                for sr, sc, start_r, start_c in (
                    (-dr, -dc, r, c),
                    (dr, dc, nr, nc),
                ):
                    rr, cc = start_r + sr, start_c + sc
                    while 0 <= rr < h and 0 <= cc < w:
                        if grid[rr][cc] != bg:
                            break
                        out[rr][cc] = color
                        rr += sr
                        cc += sc

    return out
